package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen1Test {

    /**
     * Mock implementation of ValuedEnum since the constructor is protected 
     * and it is an abstract class/interface structure.
     */
    private static class TestValuedEnum extends ValuedEnum {
        protected TestValuedEnum(String name, int value) {
            super(name, value);
        }

        @Override
        public String toString() {
            return getName();
        }
    }

    @Test
    public void testCompareTo_GreaterValue() {
        ValuedEnum enum1 = new TestValuedEnum("FIRST", 10);
        ValuedEnum enum2 = new TestValuedEnum("SECOND", 5);

        // 10 - 5 = 5
        assertEquals("Should return positive when this value is greater", 5, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_LowerValue() {
        ValuedEnum enum1 = new TestValuedEnum("FIRST", 5);
        ValuedEnum enum2 = new TestValuedEnum("SECOND", 10);

        // 5 - 10 = -5
        assertEquals("Should return negative when this value is lower", -5, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_EqualValue() {
        ValuedEnum enum1 = new TestValuedEnum("FIRST", 10);
        ValuedEnum enum2 = new TestValuedEnum("SECOND", 10);

        // 10 - 10 = 0
        assertEquals("Should return zero when values are equal", 0, enum1.compareTo(enum2));
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_WrongType() {
        ValuedEnum enum1 = new TestValuedEnum("FIRST", 10);
        Object notAnEnum = "Not an enum";

        // This should trigger the (ValuedEnum) cast exception in the method
        enum1.compareTo(notAnEnum);
    }

    @Test(expected = NullPointerException.class)
    public void testCompareTo_NullParameter() {
        ValuedEnum enum1 = new TestValuedEnum("FIRST", 10);

        // Passing null will cause a NullPointerException when attempting to access .iValue via casting
        enum1.compareTo(null);
    }
}
